dslRule:
/*!
@id: jface.text.source.addGtkCheck
@description: Extend ruler redraw condition to include GTK.
@severity: INFO
*/
org.eclipse.jface.text.source.VerticalRuler.IS_MAC_BUG_298936
=>
org.eclipse.jface.text.source.VerticalRuler.IS_MAC_BUG_298936 || org.eclipse.jface.util.Util.isGtk()
;;

beforeExample:
package org.eclipse.jface.text.source;

import org.eclipse.swt.widgets.Canvas;

// Dummy VerticalRuler and Util for compilation
class VerticalRuler {
    static final boolean IS_MAC_BUG_298936 = false;
}
class Util { public static boolean isGtk() { return false; } }

public class AnnotationRulerColumn {
    private Canvas fCanvas = new Canvas(null, 0); // Assume initialized

    public void redraw() {
        if (fCanvas != null && !fCanvas.isDisposed()) {
            if (VerticalRuler.IS_MAC_BUG_298936) { // Target pattern
                fCanvas.redraw();
                fCanvas.update();
            } else {
                // other logic
            }
        }
    }
}

afterExample:
