    public void redraw() {
        if (fCanvas != null && !fCanvas.isDisposed()) {
            if (VerticalRuler.IS_MAC_BUG_298936 || Util.isGtk()) { // Transformed
                fCanvas.redraw();
                fCanvas.update();
            } else {
                // other logic
            }
        }
    }
}

